pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed parameter is an address that we will use to initialize/act as owner via initialize() flow
    function testFuzz_property(address possibleOwner) public {
        // keep wide but avoid the zero address for the deciding case; allow zero to ensure universal property still holds
        // We will initialize contract as deployed (initialize uses msg.sender); to test generality, we use vm.prank.
        address ownerCandidate = possibleOwner;

        // ensure ownerCandidate is a valid EOA for prank calls (any address is fine for vm.prank)
        // perform initialization as ownerCandidate
        vm.prank(ownerCandidate);
        c.initialize();

        // Call the owner() getter and check it equals the stored owner (which should be ownerCandidate)
        // We capture the returned value via try/catch to follow guidelines
        address reportedOwner;
        try c.owner() returns (address o) {
            reportedOwner = o;
        } catch {
            // If owner() reverts (it shouldn't), set to zero to fail the subsequent assertion
            reportedOwner = address(0);
        }

        // The universal property: for any fuzzed ownerCandidate, after initialize() called by that account,
        // the contract's owner() must return that account (which is non-0 if possibleOwner != 0). The mutant that
        // always returns address(0) will violate this for any ownerCandidate != address(0).
        assertTrue(reportedOwner == ownerCandidate);
    }
}

