pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed by the fuzzer: an arbitrary address `caller` that will call owner().
    // General rule: for all callers, reference C.owner() returns the stored owner() value (the same regardless of caller).
    // Mutant returns msg.sender and so will differ for some callers. We fuzz caller to find such a case.
    function testFuzz_property(address caller) public {
        // make caller non-zero to be a meaningful address (keep wide domain)
        vm.assume(caller != address(0));

        // By default, after deployment, owner should be the deployer (address(this) in setUp created c from this test contract)
        // But the deployer of c was this test contract, i.e. address(this). We read storedOwner by calling c.owner() from this test (the reference behavior should return stored owner regardless of who calls),
        // so to ensure we get the stored owner, call owner() from the deployer (this test contract).
        address storedOwner = c.owner();

        // Now call owner() as the fuzzed caller. We impersonate `caller` and call c.owner().
        // We capture whether the call succeeded and the returned address.
        bool ok;
        address returned;
        vm.prank(caller);
        try c.owner() returns (address a) {
            ok = true;
            returned = a;
        } catch {
            ok = false;
            returned = address(0);
        }

        // The universal property for the correct contract: any caller's call to owner() returns the same stored owner value and does not revert.
        // Thus ok must be true and returned must equal storedOwner. The mutant that returns msg.sender will cause returned == caller, which differs from storedOwner for some caller values.
        assertTrue(ok && returned == storedOwner);
    }
}

