pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz the newOwner address. The property: when the current owner calls transferOwnership with any
    // non-zero newOwner address, owner() must equal that newOwner afterwards. The mutant that removed the
    // require(newOwner != address(0)) can still pass for non-zero inputs, but will allow address(0) to be set
    // when newOwner==address(0). We fuzz to ensure behavior for arbitrary addresses; the distinguishing
    // input (address(0)) is within the fuzz domain.
    function testFuzz_property(address newOwner) public {
        // make sure deployer is the owner: c was created by this contract in setUp()
        address deployer = address(this);
        // sanity: onlyOwner modifier requires msg.sender == owner(); ensure owner is this contract
        // initialize to set owner to this contract
        c.initialize();

        // The admissible domain is any address (including address(0)); don't exclude address(0)

        // perform the transferOwnership call as the owner (this contract)
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: for any non-zero newOwner, the call must succeed and owner() must equal newOwner.
        // This is the universal property the reference preserves; the mutant may also allow setting owner to 0
        // (or behave differently) but for some input (newOwner == address(0)) the mutant will permit owner==0
        // while the reference reverts. We assert the universal property for non-zero newOwner.
        if (newOwner != address(0)) {
            // The call must succeed and owner updated.
            assertTrue(ok && c.owner() == newOwner);
        } else {
            // For newOwner == address(0), the reference reverts (so ok==false) while the mutant may succeed.
            // We still must make exactly one assertTrue in the test overall; to satisfy the requirement we assert
            // that either the call reverted or owner is NOT address(0). The reference guarantees call reverts,
            // so this holds for all inputs on reference; the mutant will fail this for some inputs (it will set
            // owner==address(0) and ok==true), causing the test to fail on the mutant for that input.
            assertTrue(!ok || c.owner() != address(0));
        }
    }
}

