pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameter: an arbitrary address that will act as the EOA owner.
    // General idea: the reference contract requires msg.sender == owner for onlyOwner.
    // We simulate the owner being an EOA and then have a forwarding contract call transferOwnership.
    // For the correct contract, only direct EOA calls (pranked from owner) succeed; a forwarder contract
    // calling on behalf of the owner should fail because msg.sender != owner. The mutant using tx.origin
    // would allow the forwarder to succeed when tx.origin == owner.
    function testFuzz_property(address possibleOwner) public {
        // keep address non-zero and not the contract itself to be a realistic EOA
        vm.assume(possibleOwner != address(0));
        vm.assume(possibleOwner != address(this));
        vm.assume(possibleOwner != address(c));

        // Initialize c and set owner to possibleOwner by calling initialize from that EOA
        // initialize() uses initializer modifier which will set owner to msg.sender.
        vm.prank(possibleOwner);
        c.initialize();

        // Deploy a simple forwarder contract that will call c.transferOwnership(newOwner)
        Forwarder f = new Forwarder(address(c));

        // Choose a newOwner to transfer to (fuzz: use the test contract as newOwner)
        address newOwner = address(0xBEEF);

        // Now attempt: the forwarder contract will call transferOwnership on c, but the tx.origin will be the EOA
        // that we set as possibleOwner only if we send the transaction from that EOA and have it call the forwarder.
        // To model: we have possibleOwner (an EOA) call the forwarder, which then calls c.transferOwnership.
        // This models the case where tx.origin == possibleOwner but msg.sender == address(f).

        // Make the EOA (possibleOwner) call the forwarder; inside it will call c.transferOwnership(newOwner).
        vm.prank(possibleOwner);
        bool ok;
        try f.callTransferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assertion: For the correct contract, a call forwarded through another contract must NOT be accepted
        // as an onlyOwner call, so the forwarded attempt should fail (ok == false) for ALL possibleOwner values.
        // The mutant that checks tx.origin instead will allow the forwarded call to succeed for some inputs
        // (specifically when tx.origin == possibleOwner), making ok == true. Thus this assertion distinguishes them.
        assertTrue(ok == false);
    }
}

// Minimal forwarder that will call transferOwnership on target when invoked by an EOA.
contract Forwarder {
    address public target;
    constructor(address _target) { target = _target; }
    function callTransferOwnership(address newOwner) external {
        C(target).transferOwnership(newOwner);
    }
}

