pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

// This test deploys a forwarding contract that will call C.transferOwnership on behalf of an EOA.
// The correct contract requires msg.sender == owner(), so a forwarder contract (where msg.sender is the contract)
// must not be able to transfer ownership even if tx.origin == owner. The mutant that uses tx.origin will
// allow the forwarder to succeed when tx.origin == owner. We fuzz the initial owner and the candidate newOwner.

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed parameters: ownerEOA (the EOA that will be the owner), newOwner (address to transfer to)
    function testFuzz_property(address ownerEOA, address newOwner) public {
        // keep addresses non-zero to be meaningful; leave wide otherwise
        vm.assume(ownerEOA != address(0));
        vm.assume(newOwner != address(0));
        // initialize contract: call initialize() from ownerEOA so owner() == ownerEOA
        vm.prank(ownerEOA);
        c.initialize();

        // deploy a simple forwarder contract that will call c.transferOwnership(newOwner)
        Forwarder f = new Forwarder(c);

        // The forwarder will call transferOwnership with msg.sender == address(f) and tx.origin == ownerEOA
        // If the implementation correctly checks msg.sender == owner(), this should revert / fail.
        // If it incorrectly checks tx.origin == owner(), the forwarder call will succeed when tx.origin == ownerEOA.

        // Have the ownerEOA instruct the forwarder to invoke transferOwnership on its behalf (so tx.origin == ownerEOA)
        vm.prank(ownerEOA);
        bool ok;
        try f.callTransferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: the correct contract never allows a contract caller to transfer ownership
        // on behalf of an EOA owner. Therefore ok must be false for all admissible inputs.
        // The mutant that checks tx.origin will sometimes make ok == true (when tx.origin == ownerEOA),
        // so this assertion will fail on the mutant for some fuzz input.
        assertTrue(!ok);
    }
}

// Minimal forwarder that simply calls transferOwnership on target C
contract Forwarder {
    C immutable target;
    constructor(C _target) { target = _target; }
    function callTransferOwnership(address newOwner) external {
        // forward the call; msg.sender will be this contract, tx.origin will be the EOA that initiated
        target.transferOwnership(newOwner);
    }
}

