pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz the original owner EOA and the newOwner candidate; also fuzz whether the call is made directly or through a forwarder
    function testFuzz_property(address ownerEOA, address newOwner, bool viaForwarder) public {
        // Keep addresses wide but non-zero for owner and newOwner to be meaningful
        vm.assume(ownerEOA != address(0));
        vm.assume(newOwner != address(0));
        // Ensure ownerEOA is an EOA we control for prank; set some balance so tx.origin works
        vm.deal(ownerEOA, 1 ether);

        // Initialize contract with ownerEOA as owner by calling initialize from that EOA
        vm.prank(ownerEOA);
        c.initialize();

        bool ok;

        if (!viaForwarder) {
            // Direct call: msg.sender == ownerEOA
            vm.prank(ownerEOA);
            try c.transferOwnership(newOwner) {
                ok = true;
            } catch {
                ok = false;
            }
            // In the reference contract this must succeed (owner() == msg.sender), so ok == true for all admissible inputs
            assertTrue(ok);
            // Additionally ensure ownership actually changed in the reference (postcondition): owner() == newOwner
            assertTrue(c.owner() == newOwner);
        } else {
            // Via forwarder contract: deploy a tiny forwarder that will call c.transferOwnership
            Forwarder f = new Forwarder();

            // Fund forwarder so it can execute (not strictly necessary but harmless)
            vm.deal(address(f), 0.1 ether);

            // Make the ownerEOA call the forwarder which will then call c.transferOwnership(newOwner)
            // Use tx.origin = ownerEOA by prank the ownerEOA performing the external call to forwarder
            vm.prank(ownerEOA);
            // forwarder will perform an external call whose msg.sender will be the forwarder (not ownerEOA)
            try f.callTransferOwnership(address(c), newOwner) {
                ok = true;
            } catch {
                ok = false;
            }

            // In the reference contract the direct-owner requirement (msg.sender == owner) should reject this forwarded call,
            // so the transfer should fail and ownership should remain ownerEOA.
            // Therefore for the reference contract ok must be false and owner() must still equal ownerEOA.
            // We assert the universal property that in this forwarded scenario the reference rejects the forwarded call.
            assertTrue(ok == false && c.owner() == ownerEOA);
        }
    }
}

// Minimal forwarder that simply calls the target's transferOwnership
contract Forwarder {
    function callTransferOwnership(address target, address newOwner) external {
        // low-level call to preserve forwarding semantics
        (bool s, ) = target.call(abi.encodeWithSignature("transferOwnership(address)", newOwner));
        require(s, "forwarded call failed");
    }
}

